def charged_godel_universe(ck, src):
    """Stored scalar profiles across the three homogeneous charged-dust branches.
    Their constancy is checked at separated radii, including both sides of the null circle."""
    metric = "charged_godel_universe"
    views = []
    for system in ("hyperbolic", "linear", "trigonometric"):
        params = {"omega": 1.0, **({"m": 1.0} if system == "hyperbolic" else {"k": 1.0} if system == "trigonometric" else {})}
        names = list(params)
        for scalar, pid, hi, power in (("kretschmann", "K", 80, 4), ("ricci_scalar", "R", 5, 2)):
            fn = nr_published(src, metric, system, scalar, ["r"], names)
            x = axis("$\\omega r$", 0.0, 2.0)
            scale = {"kind": "linear", "from": 0.0, "to": hi}
            panel = {"id": pid, "name": f"${pid}/\\omega^{power}$", "aspect": 1,
                     "scale": scale, "ticks": value_ticks(scale)}
            shape_checks(ck, f"{metric} {system} {pid}", [1])
            values = [float(fn(r, *params.values())) for r in (0.2, 0.8, 1.5)]
            ck(f"{system} {pid} is constant across the first null circle", max(values)-min(values) < 1e-9)
            curves = line_curves(ck, f"{metric} {system}", pid, pid, fn, "r", x, scale, PLOT_W, params)
            views.append({"id": system+"_"+pid, "label": system.capitalize()+f" ${pid}$", "kind": "line",
                "x": x, "panels": [panel], "curves": curves, "marks": [],
                "legend": [["line", pid, "homogeneous curvature"]],
                "caption": [f"The {'Kretschmann' if pid == 'K' else 'Ricci'} scalar ${pid}$ of the {system} branch "
                            f"is spatially constant: ${pid}/\\omega^{power}={values[0]:g}$. "
                            "The first null circle is not a curvature singularity."],
                "settings": "$\\omega=1$"+("." if system == "linear" else ", $m=1$." if system == "hyperbolic" else ", $k=1$."),
                "clip": "Linear scale."})
    return views


DRAWN["charged_godel_universe"] = charged_godel_universe



def ghost_neutrinos(ck, src):
    """Taub's vacuum under the ghost neutrinos: K against Taub's proper distance z at L = 1.

    The stored scalar is 64/(27 z^4) with R identically zero, in every chart: the areal chart's
    and the null chart's are checked against Taub's at the same events, z = (2/3) r^(3/2) and
    r^2 = 2(mu + nu). The interval joins the embedding's inner circle z = 8L/27 to z = 4L, its
    outer one, and the logarithmic scale 10^-3 to 10^3 holds every sample. Every one of the 4001
    samples is evaluated again in sixty digits, and every written point is checked again."""
    name = "ghost_neutrinos"
    K = Published(src, name, "taub", "kretschmann", ["z"], ["L"])
    R = Published(src, name, "taub", "ricci_scalar", ["z"], ["L"])
    gzz = Published(src, name, "taub", "inverse_metric_components", ["z"], ["L"], ("z", "z"))
    z = K.coords[0]
    ck(f"{name} the stored scalar is 64/(27 z^4)", sp.simplify(K.expr - sp.Rational(64, 27) / z ** 4) == 0)
    ck(f"{name} publishes R = 0", R.expr == 0)
    areal = Published(src, name, "areal", "kretschmann", ["r"], ["L"])
    null = Published(src, name, "null", "kretschmann", ["mu", "nu"], ["L"])
    for zz in (0.3, 1.0, 3.7):
        r = (1.5 * zz) ** (2 / 3)
        want = 64 / (27 * zz ** 4)
        ck(f"{name} the areal chart's K is Taub's at z = {zz}", abs(float(areal(np.array([r]), 1.0)[0]) / want - 1) < 1e-12)
        mu = r * r / 4 + 0.3
        ck(f"{name} the null chart's K is Taub's at z = {zz}",
           abs(float(null(np.array([mu]), np.array([r * r / 2 - mu]), 1.0)[0]) / want - 1) < 1e-12)
    x_axis = axis("$z/L$", 8 / 27, 4)
    x_axis["ticks"].insert(0, {"at": 8 / 27, "label": "$8/27$"})
    scale = {"kind": "log", "from": 1e-3, "to": 1e3}
    aspect = 1.25
    panel = {"id": "K", "name": "$KL^4$", "aspect": aspect, "scale": scale, "ticks": even_decades(scale)}
    shape_checks(ck, name, [aspect])
    samples = np.linspace(x_axis["from"], x_axis["to"], SAMPLES)
    values = K(samples, 1.0)
    exact_K = sp.lambdify(K.coords + K.params, K.expr, "mpmath")
    with mpmath.workdps(60):
        worst = max(float(abs(mpmath.mpf(float(value)) / exact_K(mpmath.mpf(float(x)), mpmath.mpf(1)) - 1))
                    for x, value in zip(samples, values))
    ck(f"{name} all samples agree with the stored formula in sixty digits", worst < AGREE,
       f"worst {worst:.2e} at {len(samples)} samples")
    ck(f"{name} K is positive and falls outward", np.all(values > 0) and np.all(np.diff(values) < 0))
    ck(f"{name} has no horizon on the drawn range", np.all(gzz(samples, 1.0) > 0))
    ck(f"{name} stays inside the stated logarithmic scale",
       np.all(values >= scale["from"]) and np.all(values <= scale["to"]), f"{np.min(values):.8g} to {np.max(values):.8g}")
    ck(f"{name} K at the embedding's inner circle is 3^9/2^6 = 307.5", abs(float(K(np.array([8 / 27]), 1.0)[0]) - 3 ** 9 / 2 ** 6) < 1e-9)
    curves = line_curves(ck, name, "K", "K", K, "z", x_axis, scale, PLOT_W / aspect, {"L": 1.0})
    for curve in curves:
        agrees(ck, f"{name} every written point", K, [[x, 1.0] for x, _ in curve["points"]], [v for _, v in curve["points"]])
    return [{
        "id": "taub", "label": "$K$ against $z$", "kind": "line", "x": x_axis, "panels": [panel],
        "curves": curves, "marks": [], "legend": [["line", "K", "$K$, the Kretschmann scalar"]],
        "caption": ["The Kretschmann scalar $K = 64/27z^4$ of Taub's vacuum against the proper distance $z$ from the "
                    "singularity, the same at every $t$, $x$, and $y$ and for whatever ghost neutrino current flows "
                    "through it. It falls by $1/z^4$, from $307.5/L^4$ on the embedding's innermost circle, and "
                    "the Ricci scalar vanishes."],
        "settings": "$L = 1$.", "clip": "Logarithmic scale, $10^{-3}$ to $10^3$."}]


DRAWN["ghost_neutrinos"] = ghost_neutrinos

BEKENSTEIN_VIEWS = {   # chart: its label, its parameters, the range of eta and the scales of K and R
    "closed": ("closed universe", {"ell": 1.0, "A": 0.5}, (-math.pi, math.pi),
               {"kind": "log", "from": 1.0, "to": 1e3}, {"kind": "log", "from": 1.0, "to": 1e2}),
    "flat": ("flat universe", {"ell": 1.0, "a_b": 0.5}, (-3.0, 3.0),
             {"kind": "log", "from": 1e-3, "to": 1e3}, {"kind": "log", "from": 1e-2, "to": 1e2}),
    "open": ("open universe", {"ell": 1.0, "A": 1.5}, (-2.0, 2.0),
             {"kind": "log", "from": 1e-3, "to": 1e4}, {"kind": "log", "from": 1e-2, "to": 1e2}),
}


def bekenstein_universes(ck, src):
    """Bekenstein's three universes, both scalars against the conformal time, in units of
    l = 4 pi N mu/3, at the parameters of every other drawing.

    Each universe is homogeneous, so both stored scalars depend on eta alone and a line plot shows
    their whole variation. The checks cover R = 6 l/a^3 with the scale factor of each chart, both
    scalars greatest at the bounce eta = 0, where a is least, K = 384, 768 and 1920 there for the
    closed, flat and open universes, the closed universe's scalars periodic in eta, both scalars
    finite and above their axes everywhere drawn, and every written point in sixty digits.
    """
    name = "bekenstein_universes"
    scale = {"closed": lambda e, p: p["ell"] - p["A"] * np.cos(e),
             "flat": lambda e, p: p["a_b"] + p["ell"] * e * e / 2,
             "open": lambda e, p: p["A"] * np.cosh(e) - p["ell"]}
    bounce = {"closed": 384.0, "flat": 768.0, "open": 1920.0}
    views = []
    for system, (label, params, (lo, hi), k_scale, r_scale) in BEKENSTEIN_VIEWS.items():
        x_axis = axis("$\\eta$", lo, hi)
        panels = [{"id": "K", "name": "$K\\ell^4$", "aspect": 2, "scale": k_scale, "ticks": value_ticks(k_scale)},
                  {"id": "R", "name": "$R\\ell^2$", "aspect": 2, "scale": r_scale, "ticks": value_ticks(r_scale)}]
        shape_checks(ck, f"{name} {system}", [p["aspect"] for p in panels])
        K = Published(src, name, system, "kretschmann", ["eta"], list(params))
        R = Published(src, name, system, "ricci_scalar", ["eta"], list(params))
        eta = np.linspace(lo, hi, SAMPLES)
        values = list(params.values())
        k, r = K(eta, *values), R(eta, *values)
        a = scale[system](eta, params)
        ck(f"{name} {system}: R is 6 l/a^3", np.allclose(r, 6 / a ** 3, rtol=1e-12))
        ck(f"{name} {system}: K is {bounce[system]:g} at the bounce",
           abs(float(K(0.0, *values)) - bounce[system]) < AGREE * bounce[system])
        ck(f"{name} {system}: both scalars are greatest at the bounce",
           int(np.argmax(k)) == SAMPLES // 2 and int(np.argmax(r)) == SAMPLES // 2)
        if system == "closed":
            ck(f"{name} closed: both scalars are periodic in eta",
               abs(float(K(-math.pi, *values)) - float(K(math.pi, *values))) < AGREE
               and abs(float(R(0.3, *values)) - float(R(0.3 + 2 * math.pi, *values))) < AGREE)
        ck(f"{name} {system}: both scalars stay within their axes",
           np.min(k) > k_scale["from"] and np.max(k) < k_scale["to"]
           and np.min(r) > r_scale["from"] and np.max(r) < r_scale["to"],
           f"K from {np.min(k):.3e} to {np.max(k):.3e}, R from {np.min(r):.3e} to {np.max(r):.3e}")
        curves = (line_curves(ck, f"{name} {system}", "K", "K", K, "\\eta", x_axis, k_scale, PLOT_W / 2, params)
                  + line_curves(ck, f"{name} {system}", "R", "R", R, "\\eta", x_axis, r_scale, PLOT_W / 2, params))
        greatest = ("and least at the greatest expansion, $\\eta = \\pm\\pi$" if system == "closed"
                    else "and falling as the universe expands")
        views.append({
            "id": system, "label": label, "kind": "line", "x": x_axis,
            "panels": panels, "curves": curves, "marks": [],
            "legend": [["line", "K", "$K$"], ["line", "R", "$R = 6\\ell/a^3$"]],
            "caption": [f"The Kretschmann scalar $K$ and the Ricci scalar $R$ of the {label}, finite at every "
                        f"$\\eta$, greatest at the bounce, $\\eta = 0$, {greatest}."],
            "ricci_sentences": [],
            "per_scalar": scalar_clips("Log scale.", "Log scale."),
            "settings": "$\\ell = 1$, " + ("$a_b = 1/2$." if system == "flat" else
                                          "$A = 1/2$." if system == "closed" else "$A = 3/2$."),
            "clip": "Log scales.",
        })
    return views


DRAWN["bekenstein_universes"] = bekenstein_universes


def draw(metric_id, ck):
    src = Sources()
    views = DRAWN[metric_id](ck, src)
    ids = [v["id"] for v in views]
    ck(f"{metric_id} names each view once", len(set(ids)) == len(ids), f"{ids}")
    # The page shows a view that draws both scalars in two places, its Ricci scalar after the Ricci
    # scalar, and takes the sentences of its caption that go there from `ricci_sentences`.
    for v in views:
        ricci = build.curvature_ricci_panels(v)
        if any(ricci) and not all(ricci):
            if "per_scalar" in v:
                place_legends(ck, metric_id, v)
            ck(f"{metric_id} {v['id']} states the scale of each of its two places", "per_scalar" in v)
            problem = "it names none"
            if "ricci_sentences" in v:
                try:
                    build.check_ricci_sentences(v["id"], v)
                    problem = None
                except build.DataError as exc:
                    problem = str(exc)
            ck(f"{metric_id} {v['id']} says which sentences of its caption are the Ricci scalar's", problem is None,
               problem or "")
    return {"metric": metric_id, "source": src.stamps(), "views": views}


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--metric", action="append", default=[], help="redraw only this spacetime, repeatable")
    parser.add_argument("--verify", action="store_true", help="run and print every check instead of writing")
    args = parser.parse_args(argv)
    unknown = set(args.metric) - set(DRAWN)
    if unknown:
        parser.error(f"no curvature figure is drawn for {sorted(unknown)}")
    wanted = [m for m in DRAWN if not args.metric or m in args.metric]
    start = time.time()
    ck = Checks()
    files = {metric_id: draw(metric_id, ck) for metric_id in wanted}
    if args.verify:
        ck.report()
    failed = ck.failures()
    print(f"{len(ck.made)} checks in {time.time() - start:.1f} s, {len(failed)} failed",
          file=sys.stderr if failed else sys.stdout)
    for name in failed:
        print(f"FAILED {name}", file=sys.stderr)
    if failed or args.verify:
        return 1 if failed else 0
    CURVATURE_DIR.mkdir(parents=True, exist_ok=True)
    if not args.metric:
        # A spacetime that is not drawn has no file, so a full redraw removes one left behind.
        for path in sorted(CURVATURE_DIR.glob("*.json")):
            if path.stem not in DRAWN and not build.CONFLICT_COPY.search(path.stem):
                path.unlink()
                print(f"removed {path.relative_to(build.ROOT)}")
    for metric_id, data in files.items():
        view_text.warn(f"{metric_id} curvature", data["views"])
        path = CURVATURE_DIR / f"{metric_id}.json"
        path.write_text(json.dumps(data, ensure_ascii=False, separators=(",", ":")) + "\n", encoding="utf-8")
        print(f"wrote {path.relative_to(build.ROOT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
